SELECT *, MAX(quantity) OVER (PARTITION BY product_id ORDER BY last_restock, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_max_quantity, COUNT(quantity) OVER (PARTITION BY product_id ORDER BY last_restock, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_count_quantity, SUM(quantity) OVER (PARTITION BY product_id ORDER BY last_restock, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_sum_quantity, AVG(quantity) OVER (PARTITION BY product_id ORDER BY last_restock, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS last7_avg_quantity FROM inventory;
